import os
import boto3

def extract_tables(payload, config=None):
    config = config or {}
    client = boto3.client('textract', region_name=config.get('region', 'us-east-1'))
    response = client.analyze_document(
        Document={'Bytes': payload},
        FeatureTypes=['TABLES']
    )
    blocks = response['Blocks']
    block_map = {block['Id']: block for block in blocks}
    def get_text(block):
        text = ''
        if 'Relationships' in block:
            for rel in block['Relationships']:
                if rel['Type'] == 'CHILD':
                    for child_id in rel['Ids']:
                        child = block_map[child_id]
                        if child['BlockType'] == 'WORD':
                            text += child['Text'] + ' '
        return text.strip()
    def find_tables_with_cells():
        tables = []
        for block in blocks:
            if block['BlockType'] == 'TABLE':
                table_cells = []
                if 'Relationships' in block:
                    for rel in block['Relationships']:
                        if rel['Type'] == 'CHILD':
                            for cid in rel['Ids']:
                                cell = block_map[cid]
                                if cell['BlockType'] == 'CELL':
                                    row_idx = cell['RowIndex']
                                    col_idx = cell['ColumnIndex']
                                    rowspan = cell.get('RowSpan', 1)
                                    colspan = cell.get('ColSpan', 1)
                                    text = get_text(cell)
                                    table_cells.append({
                                        'RowIndex': row_idx,
                                        'ColumnIndex': col_idx,
                                        'RowSpan': rowspan,
                                        'ColSpan': colspan,
                                        'Text': text
                                    })
                if table_cells:
                    row_groups = {}
                    for cell in table_cells:
                        row = cell['RowIndex']
                        if row not in row_groups:
                            row_groups[row] = []
                        row_groups[row].append(cell)
                    table_rows = []
                    for row_idx in sorted(row_groups):
                        row_cells = sorted(row_groups[row_idx], key=lambda c: c['ColumnIndex'])
                        row_data = []
                        for cell in row_cells:
                            row_data.append({
                                'text': cell['Text'],
                                'colspan': cell['ColSpan']
                            })
                        table_rows.append(row_data)
                    tables.append({'rows': table_rows})
        return tables
    result = find_tables_with_cells()
    return result
